    <script>
    document.addEventListener('DOMContentLoaded', function() {
        // --- 开始修改：随机背景图片逻辑 ---
        const backgroundImages = [
            'https://files.catbox.moe/j8w7j0.jpeg',
            'https://files.catbox.moe/3e6ea2.jpeg',
            'https://files.catbox.moe/i8lrdc.jpeg',
            'https://files.catbox.moe/120sq7.jpeg',
            'https://files.catbox.moe/75jz12.jpeg',
            'https://files.catbox.moe/b9rjw9.jpeg'
        ];
        const randomIndex = Math.floor(Math.random() * backgroundImages.length);
        const randomImage = backgroundImages[randomIndex];
        const mainContent = document.querySelector('.p10-main-content');
        if (mainContent) {
            mainContent.style.backgroundImage = `url('${randomImage}')`;
        }
        // --- 结束修改 ---

        const getData = (id) => document.querySelector(`.p10-data-source [data-id="${id}"]`)?.textContent.trim() || '';

        const data = {
            time: getData('time'), location: getData('location'),
            userName: getData('userName'), userTitle: getData('userTitle'),
            intel: getData('intel'), quest: getData('quest'),
            npc: {
                name: getData('npcName'), age: getData('npcAge'), personality: getData('npcPersonality'),
                role: getData('npcRole'), cultivation: getData('npcCultivation'), body: getData('npcBody'),
