                thigh: getData('npcThigh'), foot: getData('npcFoot'), specialStatus: getData('npcSpecialStatus'),
                emotion: getData('npcEmotion'), posture: getData('npcPosture'), thought: getData('npcThought'),
            }
        };

        const ui = {
            tabs: document.querySelectorAll('.p10-side-tab'),
            panels: document.querySelectorAll('.p10-content-panel'),
            header: {
                userName: document.getElementById('p10-user-name'),
                userTitle: document.getElementById('p10-user-title'),
                date: document.getElementById('p10-date'),
                location: document.getElementById('p10-location'),
            },
            npcPanel: {
                name: document.getElementById('p10-npc-name'),
                age: document.getElementById('p10-npc-age'),
                cultivation: document.getElementById('p10-npc-cultivation'),
                role: document.getElementById('p10-npc-role'),
                personality: document.getElementById('p10-npc-personality'),
                appearance: document.getElementById('p10-npc-appearance'),
                bodyStatus: document.getElementById('p10-npc-body-status'),
                posture: document.getElementById('p10-npc-posture'),
                thought: document.getElementById('p10-npc-thought'),
            },
            intelList: document.getElementById('p10-intel-list'),
            questDetails: document.getElementById('p10-quest-details'),
        };

        function renderHeader() {
            ui.header.userName.textContent = data.userName || '天命之人';
            ui.header.userTitle.textContent = data.userTitle || '身份未知';
            ui.header.date.textContent = data.time || '时辰未知';
            ui.header.location.textContent = data.location || '位置未知';
        }

        function renderNpcPanel() {
            if (!data.npc.name) {
                document.querySelector('[data-target="p10-panel-npc"]').style.display = 'none';
                return;
            }
            const npc = data.npc;
            ui.npcPanel.name.textContent = npc.name;
            ui.npcPanel.age.textContent = npc.age;
            ui.npcPanel.cultivation.textContent = npc.cultivation;
            ui.npcPanel.role.textContent = npc.role;
            ui.npcPanel.personality.textContent = npc.personality;
            ui.npcPanel.appearance.innerHTML = `身体: ${npc.body}<br>套装: ${npc.set}<br>衣着: ${npc.clothing}<br>鞋袜: ${npc.footwear}<br>配饰: ${npc.acc}<br>特殊装扮: ${npc.specialOutfit}`;
            ui.npcPanel.bodyStatus.innerHTML = `口腔: ${npc.mouth}<br>乳房: ${npc.breast}<br>手部: ${npc.hand}<br>小腹: ${npc.belly}<br>小穴: ${npc.vagina}<br>子宫: ${npc.womb}<br>后庭: ${npc.anus}<br>大腿: ${npc.thigh}<br>足部: ${npc.foot}`;
            ui.npcPanel.posture.innerHTML = `情绪: ${npc.emotion}<br>姿势: ${npc.posture}<br>特殊状态: ${npc.specialStatus}`;
            ui.npcPanel.thought.textContent = npc.thought;
        }

        function renderIntelPanel() {
            const intelItems = data.intel.split(/\n(?=\d\.\s*内容：)/).filter(Boolean);
            if(intelItems.length === 0 || !data.intel) {
                 document.querySelector('[data-target="p10-panel-intel"]').style.display = 'none';
                 return;
            }
            ui.intelList.innerHTML = intelItems.map(item => {
                const contentMatch = item.match(/内容：([\s\S]*?)(?=\s*（来源：|$)/);
                const sourceMatch = item.match(/（来源：(.*?)\）/);
                const content = contentMatch ? contentMatch[1].trim() : '内容未知';
                const source = sourceMatch ? sourceMatch[1].trim() : '来源未知';
                return `<div class="p10-list-item">
                            <p>${content}</p>
                            <div class="source">- ${source}</div>
                        </div>`;
            }).join('');
        }

        function renderQuestPanel() {
            if (!data.quest) {
                 document.querySelector('[data-target="p10-panel-quest"]').style.display = 'none';
                 return;
            }
            const questData = {};
            data.quest.split('\n').forEach(line => {
                const parts = line.split('：');
                if (parts.length > 1) {
                    questData[parts[0].trim()] = parts.slice(1).join('：').trim();
                }
            });
            ui.questDetails.innerHTML = `
                <div class="p10-list-item">
                    <p><strong>目标：</strong> ${questData['任务目标'] || '未知'}</p>
                    <p><strong>内容：</strong> ${questData['任务内容'] || '未知'}</p>
                </div>
                <div class="p10-list-item">
                    <p><strong>来源：</strong> ${questData['任务来源'] || '未知'}</p>
                    <p><strong>奖励：</strong> ${questData['任务奖励'] || '未知'}</p>
                </div>
            `;
        }

        // Tab switching logic
        ui.tabs.forEach(tab => {
            tab.addEventListener('click', () => {
                ui.tabs.forEach(t => t.classList.remove('active'));
                ui.panels.forEach(p => p.classList.remove('active'));

                tab.classList.add('active');
                const targetPanel = document.getElementById(tab.dataset.target);
                if (targetPanel) {
                    targetPanel.classList.add('active');
                }
            });
        });

        // Initial render and default tab activation
        renderHeader();
        renderNpcPanel();
        renderIntelPanel();
        renderQuestPanel();

        // Activate the first visible tab by default
        const firstVisibleTab = Array.from(ui.tabs).find(tab => tab.style.display !== 'none');
        if (firstVisibleTab) {
            firstVisibleTab.click();
        }

    });
    </script>
</body>
</html>
