  .selection-container::after {
    right: -40px;
  }

  /* --- Stylized Title --- */
  .selection-title {
    text-align: center;
    color: #3a2d0d;
    font-size: 2em;
    margin-bottom: 30px;
    font-weight: 700;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .selection-title::before,
  .selection-title::after {
    content: '';
