    scrollbar-width: thin;
    scrollbar-color: #c8a46e #fdfaf2;
  }
  .job-list::-webkit-scrollbar { width: 8px; }
  .job-list::-webkit-scrollbar-track { background: #fdfaf2; border-radius: 4px; }
