    left: 10%;
    right: 10%;
    height: 1px;
    background: radial-gradient(circle, #c8a46e 1px, transparent 1.5px);
    background-size: 10px 1px; /* Creates a dotted line effect */
    opacity: 0.7;
  }

  .job-item {
    padding: 10px;
    cursor: pointer;
    transition: background-color 0.3s, transform 0.2s, box-shadow 0.3s;
    border-radius: 8px;
  }

  .job-item:hover {
    background-color: #fffde7;
    transform: translateY(-3px) scale(1.01);
    box-shadow: 0 5px 20px rgba(184, 134, 11, 0.2);
  }

  .job-title {
    font-weight: bold;
    color: #5c3f06;
    font-size: 1.2em;
    display: block;
    margin-bottom: 5px;
  }

  /* --- Automatic Numbering using CSS Counter --- */
  .job-title::before {
    counter-increment: job-counter;
    content: counter(job-counter) ". ";
    color: #a07d39; /* Golden color for numbers */
    font-weight: 700;
    margin-right: 8px;
  }

  .job-description {
    color: #7a5d2d;
    font-size: 0.95em;
    line-height: 1.6;
    padding-left: 2em; /* Align description with title text */
  }

  /* --- Responsiveness for smaller screens --- */
  @media (max-width: 600px) {
    .selection-container {
      padding: 20px;
      border-width: 10px;
    }
    .selection-container::before,
    .selection-container::after {
      display: none; /* Hide scroll rollers on small screens */
    }
    .selection-title {
      font-size: 1.5em;
    }
    .job-title {
      font-size: 1.1em;
    }
    .job-description {
