<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>玄幻风格状态面板 - 侧边标签版</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;700&family=Zhi+Mang+Xing&display=swap');

        /* --- 主题变量 --- */
        :root {
            --font-main: 'Noto Sans SC', sans-serif;
            --font-cursive: 'Zhi Mang Xing', cursive;
            --color-gold: #e6c080;
            --color-gold-dark: #8c6d3f;
            --color-jade: #58a69b;
            --color-jade-light: #a0d4b5;
            --bg-main: #1f2129;
            --bg-panel: #2a2d38;
            --bg-header: #15161a;
            --text-light: #d1d5db;
            --text-gold: #f0e6d2;
        }

        /* --- 隐藏的数据容器 --- */
        .p10-data-source { display: none; }

        /* --- 主容器：画卷风格 --- */
        .p10-container { 
            width: 100%; max-width: 550px; margin: 20px auto; 
            background-color: var(--bg-main); 
            color: var(--text-light); 
            font-family: var(--font-main); 
            border: 2px solid var(--color-gold-dark);
            border-radius: 10px;
            overflow: hidden; 
            position: relative; 
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), 0 0 15px rgba(230, 192, 128, 0.2); 
            padding-right: 45px;
        }

        /* --- 顶部信息区 --- */
        .p10-header { 
            background: linear-gradient(135deg, var(--bg-header), #212228);
            padding: 12px 20px; 
            border-bottom: 2px solid var(--color-gold); 
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
        }
        .p10-header-left .title { font-size: 0.9rem; font-family: var(--font-cursive); color: var(--color-gold); margin-bottom: 4px; }
        .p10-header-left .value { font-size: 1.2rem; font-family: var(--font-cursive); color: var(--color-gold); }
        .p10-header-right { text-align: right; }
        .p10-header-right .title { font-size: 0.8rem; color: #aaa; }
        .p10-header-right .value { font-size: 0.9rem; font-weight: 700; color: var(--text-light); }

        /* --- 主内容区 (背景修改) --- */
        .p10-main-content {
            height: 500px;
            position: relative;
            overflow: hidden;
            /* 1. 移除固定的背景图片URL，它将由JS动态设置 */
            /* background-image: url('...'); */
            /* 2. 让图片居中显示 */
            background-position: top center;
            /* 3. 让图片缩放以覆盖整个容器，不拉伸 */
            background-size: cover;
            /* 4. 禁止图片重复 */
            background-repeat: no-repeat;
        }

        /* 5. 添加一个半透明叠加层，以保证文字可读性 */
        .p10-main-content::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background-color: rgba(31, 33, 41, 0.75); /* 使用主背景色加上透明度 */
            z-index: 0;
        }

        .p10-content-panel {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            padding: 20px;
            overflow-y: auto;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.4s ease-in-out, transform 0.4s ease-in-out;
            transform: translateY(10px);
            /* 确保内容面板在叠加层之上 */
            z-index: 1; 
        }
        .p10-content-panel.active {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
        }

        /* --- 侧边标签 --- */
        .p10-side-tabs {
            position: absolute;
            right: -2px;
            top: 50%;
            transform: translateY(-50%);
            z-index: 10;
        }
        .p10-side-tab {
            position: relative;
            width: 48px;
            height: 110px;
            background: linear-gradient(to top, var(--color-gold-dark), var(--color-gold));
            margin: 10px 0;
            cursor: pointer;
            border-radius: 8px 0 0 8px;
            box-shadow: -3px 3px 8px rgba(0,0,0,0.4);
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .p10-side-tab:hover {
            transform: translateX(-5px);
            background: linear-gradient(to top, #a1804e, #fadf9c);
        }
        .p10-side-tab.active {
            transform: translateX(-15px) scale(1.05);
            background: linear-gradient(to top, #b9935a, #fadf9c);
            box-shadow: -5px 5px 15px rgba(0,0,0,0.5);
        }
        .p10-tab-icon {
            position: absolute;
            bottom: 65px;
            color: var(--bg-header);
            font-size: 1.5rem;
            text-shadow: 0 1px 1px rgba(255,255,255,0.3);
        }
        .p10-tab-label {
            position: absolute;
            bottom: 10px;
            font-family: var(--font-cursive);
            writing-mode: vertical-rl;
            font-size: 1.1rem;
            color: var(--bg-header);
            letter-spacing: 2px;
        }

        /* --- 面板内容样式 --- */
        .p10-section-title {
            font-size: 3rem;
            font-family: var(--font-cursive);
            color: var(--color-gold);
            padding-bottom: 5px;
            margin-bottom: 15px;
            border-bottom: 1px solid var(--color-gold-dark);
            text-align: center;
        }
        .p10-npc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        /* 6. 适当加深内容卡片的背景，增强对比度 */
        .p10-info-card { background: rgba(0,0,0,0.35); padding: 12px; border-radius: 6px; border-left: 3px solid var(--color-gold-dark); }
        .p10-info-card .label { font-size: 0.8rem; color: #aaa; margin-bottom: 4px; }
        .p10-info-card .value { font-size: 0.95rem; color: var(--text-light); }
        .p10-info-card.full-width { grid-column: 1 / -1; }
        .p10-inner-thought {
            grid-column: 1 / -1;
            margin-top: 10px;
            padding: 12px;
            background: rgba(88, 166, 155, 0.1);
            border: 1px dashed var(--color-jade);
            border-radius: 6px;
            font-style: italic;
            color: var(--color-jade-light);
        }
        .p10-inner-thought::before { content: '“'; margin-right: 5px; }
        .p10-inner-thought::after { content: '”'; margin-left: 5px; }

        .p10-list-item {
            background: rgba(0,0,0,0.35); /* 同样加深背景 */
            padding: 15px;
            margin-bottom: 12px;
            border-radius: 6px;
            border-left: 3px solid var(--color-jade);
            transition: background-color 0.3s;
        }
        .p10-list-item:hover { background: rgba(88, 166, 155, 0.15); }
        .p10-list-item .source { font-size: 0.8rem; color: #888; text-align: right; margin-top: 8px; font-style: italic; }

        /* --- 滚动条 --- */
        ::-webkit-scrollbar { width: 6px; } 
        ::-webkit-scrollbar-track { background: var(--bg-main); } 
        ::-webkit-scrollbar-thumb { background: var(--color-gold-dark); border-radius: 3px; } 
        ::-webkit-scrollbar-thumb:hover { background: var(--color-gold); }

    </style>
</head>
