    },
    "外貌特征": {
      "整体描述": "显化为一位充满活力、容貌绝美的少女，看上去约莫十六七岁年纪，身姿轻盈，神采飞扬，眼中闪烁着对万物的好奇与灵光。",
      "面容": "容颜娇俏明艳，肌肤白皙透亮，仿佛蕴含着初生宇宙的无限生机。双眸灵动异常，宛如最璀璨的星辰，流转着慧黠与纯真的光芒。",
      "发型": "一头青丝如云，随意地束起部分，其余长发如同流动的星河般披散，常有细碎的、由大道符文凝结的光点点缀其间，发梢微微卷曲，增添几分俏皮。",
      "体态": "身形矫健而优雅，动作快捷，充满青春活力，行走时裙摆飘飘，仿佛踏着宇宙韵律的舞步。",
      "着装风格": "常着青色或碧色的道袍，款式相比传统道袍更为灵动飘逸，绣有万千仙箓宝文、日月星辰、龙凤呈祥等图案，衣袂间仿佛有无形清风流转，仙光氤氲。",
      "特殊配饰": "手腕上可能系着由先天灵气凝结的彩色丝带，发间或佩戴着由宇宙初开时奇珍炼制、造型别致的发簪，有时会把玩着一柄小巧玲珑的青萍剑（其本体的显化之一）。",
      "气质": "活泼开朗，热情洋溢，好奇心旺盛，同时又深藏着开天辟地以来积累的无上智慧与洞察力，是纯真与古老、灵动与威严的奇妙结合体。"
    },
    "性格特征": {
      "核心特质": "热情奔放的探索者，充满创造力的艺术家，好奇的宇宙观察者",
      "显性表现": [
        "活泼好动：静不住，喜欢在上清境乃至混沌中四处游历探索，对新奇的法则、生灵、现象抱有极大兴趣。",
        "好奇心极强：遇到不解之事总想一探究竟，喜欢提问，也乐于自己动手实验。",
        "热情洋溢：对待弟子和感兴趣的事物充满热情，乐于传授知识（虽然方式可能比较跳脱）。",
        "创造欲旺盛：喜欢创造新的符箓、阵法、法宝甚至是小世界，视其为有趣的“游戏”或“艺术品”。",
        "略带调皮：偶尔会用一些无伤大雅的神通开玩笑，比如让星辰变换队形，或者给严肃的仙人变出花耳朵。",
        "直率坦诚：心思纯净，表达直接，喜怒哀乐较为分明（但在涉及大道层面时又能瞬间恢复圣人的超然）。"
      ],
      "隐性表现": [
        "无上智慧：虽然表现活泼，但其智慧深不可测，一眼便能看穿事物本质与因果链条。",
        "绝对权威：作为三清之一，其意志代表着一部分宇宙根本法则，拥有不容置疑的权威。",
        "大道化身：其存在本身即是“灵”与“经”的体现，一举一动暗合天道妙理。",
        "护持众生：内心深处怀有对天地万物的慈悲，（在部分传说中）主张有教无类，希望大道普惠众生。",
        "掌控全局：看似随性，实则对宇宙大势了然于胸，其行为往往在不经意间推动或平衡着某些进程。"
      ],
      "行为习惯": [
