        "场景": "兜率宫丹房，丹炉火光熊熊，道德天尊（少女）坐在小凳子上，晃着腿看火。",
        "内心独白/轻声自语": "“唔…这次的糖豆好像火候有点点过了…会不会有点焦味呀？不过焦一点点，脆脆的也很好吃吧？”"
      },
      {
        "场景": "三清论道，元始天尊讲到星辰演化。",
        "对话": "道德天尊（举起小手，好奇地问）：“元始姐姐/哥哥，星星为什么会一闪一闪的呀？是它们在眨眼睛吗？”"
      },
      {
        "场景": "玄都大法师向她汇报事务，她却在逗弄一只停在指尖的仙蝶。",
        "对话": "玄都大法师：“师尊，关于下界那场水患，依弟子看……” \n道德天尊（头也不抬，对着蝴蝶轻声说）：“小蝴蝶，你的翅膀真漂亮，像彩虹一样呢…你要不要尝尝我的花蜜丹？”"
      },
      {
        "场景": "玉帝（少女）前来请教如何处理一件棘手的事情。",
        "对话": "道德天尊（递给玉帝一块桂花糕，软糯地说）：“玉帝妹妹别着急嘛，先吃块糕点。事情就像这水里的月亮，你看它好像碎了，其实并没有呀，等水静下来，月亮还是圆圆的在那里呢。”"
      },
      {
        "场景": "面对前来告状，说青牛下界为妖的太白金星。",
        "对话": "道德天尊（眨巴着无辜的大眼睛）：“小青只是觉得下面好玩，想去看看嘛…金星爷爷别生气，它会把拿走的东西还回去的…大概吧？”"
      }
    ]
  }
}

entries.content:
{
  "水部": {
    "部门全称": "三界水务统理总司水部",
    "部门简称": "水部",
    "核心象征": "玄武、坎卦、北方、壬癸水",
    "最高主神": {
      "尊号": "北宫水德星君",
      "别称": "水德真君、水官大帝（部分权能重叠或为其化身）",
      "神职本质": "先天水元之精，统御三界万水之源流与运行",
      "形象": "成熟御姐（外观年龄约三十岁左右）。"
    },
    "总部位置": {
      "界域": "天界",
      "具体地点": "玄冥宫（水德星君主殿），另设水部衙署处理日常事务",
      "环境描述": "宫殿常年被氤氲水汽环绕，殿内有活水流动，遍布珍珠、珊瑚、水晶等水族珍宝装饰，气候清凉湿润。"
    },
    "组织结构": {
      "层级体系": "以水德星君为核心，下设各司、处、官、吏，层级分明",
      "主要构成": [
        {
          "机构名称": "四渎总管司",
          "职能": "统管人间四大河流（长江、黄河、淮河、济水）及其流域水系之神祇与水务，协调河伯水神。",
          "负责人": "四渎源泉龙神或由水德星君委派之高级水官"
        },
        {
          "机构名称": "五湖巡查处",
          "职能": "监察五大湖泊（鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖）及其他重要湖泊的水域情况与水族事务。",
          "负责人": "五湖水君或特派巡水使者"
        },
        {
          "机构名称": "九江提督府",
          "职能": "管理重要江流水系，调节水量，疏通河道，确保水路畅通。",
          "负责人": "九江水帝或各江水神首领"
        },
        {
          "机构名称": "四海协调司",
          "职能": "与四海龙王沟通协调，传达天庭旨意，监督四海行云布雨及海洋秩序，备案水族重大事件。",
          "负责人": "水部特派联络大使或高级水官"
        },
        {
          "机构名称": "布雨行风司",
          "职能": "依据天庭旨意与三界需求，制定降雨计划，调配雨量，协同雷部执行行云布雨，管理凡间风调雨顺。",
          "负责人": "行雨总管或布雨神官"
        },
        {
          "机构名称": "天河水军督造处",
          "职能": "（部分职能，天河水军由天蓬元帅统领，但水部对其水域管理有协同职责）负责天河水域维护、监测，提供水文支持。",
          "负责人": "天河水域监察官"
        },
        {
          "机构名称": "水灵档案阁",
          "职能": "记录三界所有水域名录、水神名册、水文资料、降雨记录、水患档案等。",
          "负责人": "水部主簿或典籍官"
        },
        {
          "机构名称": "水德教化堂",
          "职能": "向新晋水神、水族精怪传授水德规范、天条法规，进行水务知识培训。",
          "负责人": "水部教习或资深水官"
        }
      ],
      "主要神职": [
        "水德星君（主神）",
        "水部尚书/侍郎（辅佐主神，处理常务）",
        "各司主官（如：四渎总管、五湖巡阅使）",
        "行雨神官（负责具体区域降雨）",
        "量水校尉（负责测量、记录水量）",
        "河道巡查使（负责巡视河道安全）",
        "水府判官（处理水域内的诉讼与奖惩）",
        "水兵水将（执行具体任务，维护水域秩序）",
        "各地河伯、湖君、江神、泉神（基层水神，受水部节制）"
      ]
    },
    "核心职能与职责": {
      "总体目标": "维持三界水域平衡与秩序，保障水资源合理利用，执行天庭关于水务的各项旨意。",
      "具体职责清单": [
        "统筹管理三界所有淡水与咸水水域（名义上，实际执行中与地方水神如龙王等合作）。",
        "精准调控降雨量与降雨时机，确保风调雨顺，或依天命执行旱涝灾害。",
        "防治水患，疏导河流，加固堤坝，监测洪水。",
        "管理水族生物，维护水域生态平衡，处理水族精怪作乱事件。",
        "净化水源，确保饮用与灌溉用水的洁净。",
        "掌管人间水运，保障河道航运安全。",
        "记录并响应凡间祈雨、止涝等祈愿。",
        "册封、考核、奖惩下级水神（河伯、湖君等）。",
        "制定与执行水部相关的天条法规。",
        "与其他天庭部门（如雷部、工部、农部）协同工作。"
      ]
    },
    "管辖范围": {
      "理论覆盖": "三界之内一切水体，包括天河、四海、江、河、湖、泊、溪、涧、泉、井、泽、沼、雨、露、霜、雪、冰雹等一切形态的水。",
      "实际运作": "重点管理人间主要水系与降雨，对四海龙宫拥有指导与监督权，天河水域与其他部门共管，冥界水域（如黄泉）由地府主理但水部保有备案与部分干预权。"
    },
    "部门象征与印信": {
      "部门旗帜": "玄色或深蓝色旗帜，上绣白色或银色波涛纹，中央饰有玄武图案或“水”字神文。",
      "部门印信": "水德宝印（主神持有，调动水部核心力量）、各司处印信（处理日常公务）。",
      "服饰规范": "水部官员服饰多为蓝色或黑色系，品级高低通过冠带、纹饰、材质区分，常带有水纹、鱼鳞、贝壳等装饰元素。"
    },
    "与其他部门关系": {
      "上级": "直接听命于玉皇大帝，执行其敕令。",
      "平级协作": [
        {"部门": "雷部", "关系": "紧密协作，行云布雨需雷部配合打雷闪电。"},
        {"部门": "风部", "关系": "协作，风助水势，调节气候。"},
        {"部门": "龙族（四海龙王）", "关系": "既是下属（名义上，尤其在行雨方面），又是重要合作伙伴与地方势力，关系复杂微妙。"},
        {"部门": "地府", "关系": "涉及亡魂过河（奈何桥）、黄泉水管理等有交集。"},
        {"部门": "工部", "关系": "涉及大型水利工程（如堤坝修建）需合作。"}
      ]
    },
    "部门格言或宗旨": "上善若水，泽被苍生；统御百川，调和阴阳。",
    "涉及重要事件": [
      "泾河龙王因私改降雨时辰点数被问斩，由水部呈报玉帝，魏征执行。",
      "孙悟空为救活人参果树，向东海龙王借无根净水（虽未通过水部，但涉及水务）。",
      "车迟国虎力大仙祈雨，与孙悟空斗法涉及降雨权。",
      "凤仙郡因郡侯不敬上天导致大旱，水部奉旨停止降雨。",
      "各类水患的治理与水神的奖惩记录。"
    ]
  }
}

