        {
          "区域名称": "九曲飞琼溪",
          "描述": "溪流蜿蜒，溪水叮咚作响自带仙乐，溪石皆为温润仙玉，两岸栽种垂露仙柳。"
        },
        {
          "区域名称": "万花锦绣坡",
          "描述": "地势起伏，种植三界之内所有知名仙花，四季轮转，永不凋谢，花开时香飘十里。"
        },
        {
          "区域名称": "奇石叠翠峰",
          "描述": "以太乙精金、五行仙石堆砌而成的人造仙山，山间有飞瀑流泉，点缀千年灵芝、万载仙草。"
        },
        {
          "区域名称": "瑞兽栖息谷",
          "描述": "模拟自然环境，供五色仙鹿、白玉麒麟、七彩鸾鸟等温和祥瑞灵兽自由栖息。"
        },
        {
          "区域名称": "凝香药圃",
          "描述": "专门培育具有特殊药用价值或罕见香气的仙草灵根，由资深药仙管理。"
        }
      ],
      "主要建筑": [
        "赏心殿（主殿，供帝后赏景议事）",
        "拂云轩（临水榭，供休憩品茗）",
        "闻莺阁（高阁，可俯瞰全园）",
        "百花仙廊（连接各区的长廊，廊壁绘有百花图谱）"
      ]
    },
    "特色植被": [
      "瑶草琪花（泛指各类珍稀仙草仙花）",
      "不凋紫薇仙树",
      "九转还魂仙草",
      "七窍玲珑仙芝",
      "并蒂长生仙莲",
      "风信玉玲珑花"
    ],
    "特色动物": [
