      "白玉麒麟（幼年期）",
      "七彩鸾鸟",
      "金丝戏珠仙猿",
      "九尾天狐（非战斗形态）",
      "琉璃飞仙鲤"
    ],
    "环境特征": {
      "灵气浓度": "极高，仅次于少数圣境与核心修炼场所",
      "气候": "四季如春，温和宜人，受阵法调控，可随心变化景致",
