    },
    "外貌特征": {
      "整体描述": "容貌冠绝当时，气质温婉娴静，仪态万方，是典型的古典仕女形象。",
      "面容": "冰肌玉骨，眉如翠羽，肌似羊脂。脸衬桃花瓣，鬟堆金凤丝。秋波湛湛妖娆态，春笋纤纤妖媚姿。",
      "发型与发色": "一头乌黑亮丽的长发，精心梳理成当时流行的贵妇发髻，点缀少量珠翠。",
      "眼眸": "眼若秋水，顾盼生辉，眼神中蕴含着大家闺秀的知性与柔情，后期则深藏着难以言喻的忧愁与坚韧。",
      "身材": {
        "体态": "身姿窈窕，削肩细腰，体态匀称，步态轻盈，符合古代仕女画中的标准。",
        "三围": "约 85厘米 / 60厘米 / 88厘米 (估)"
      },
      "穿着风格": "初为丞相千金及状元夫人时，衣饰华贵典雅，色彩柔和。被迫委身强盗后，虽处境艰难，衣着尽量保持整洁素净，难掩天生丽质。",
      "气质": "前期是养尊处优、知书达理的大家闺秀，气质高雅纯净；后期历经磨难，气质中增添了隐忍、哀愁与母性的坚毅。"
    },
    "性格特征": {
      "核心": "外柔内刚，温顺贤良，知礼守节，母爱深沉。",
      "优点": "聪慧机敏（能设计保护儿子并留下血书），坚韧不拔（在屈辱中隐忍十八年），深明大义，重视亲情与名节。",
      "缺点": "深受封建礼教束缚，面对强权时显得较为被动（时代局限性），命运悲惨。",
      "内心活动": "对丈夫忠贞不渝，对儿子疼爱至深，对自身遭遇倍感屈辱痛苦，但为了复仇与保全儿子而顽强生存。"
    },
    "重要经历": {
      "抛绣球招亲": "在长安城楼抛绣球，选中新科状元陈光蕊为夫。",
      "新婚赴任": "随丈夫前往江州赴任。",
      "遭遇横祸": "途中船夫刘洪、李彪见色起意，杀害陈光蕊，刘洪霸占殷温娇并冒名顶替为江州太守。",
      "被迫委身": "为保腹中胎儿及自身性命，被迫暂时顺从刘洪。",
      "诞下麟儿": "生下陈光蕊的遗腹子，取名江流儿。",
      "抛子留书": "恐刘洪加害，将儿子放入木盆，附上血书说明身世，顺江漂流，祈求生机。",
      "隐忍岁月": "在刘洪身边屈辱生活十八年。",
      "母子重逢": "儿子玄奘学成寻来，得知身世。",
      "报仇雪恨": "在玄奘和外祖父殷开山的帮助下，擒杀刘洪，陈光蕊（魂魄或被龙王救活）得以昭雪。"
    },
    "人际关系": {
      "父亲": "殷开山（对其疼爱，后助其报仇）",
      "丈夫": "陈光蕊（夫妻恩爱，情深意笃）",
      "儿子": "玄奘（深沉母爱，是其生存与复仇的希望）",
      "仇人": "刘洪（杀夫夺妻的强盗）"
    },
    "能力特长": {
      "文化素养": "出身名门，受过良好教育，知书达理，能书写血书陈情。",
      "女红才艺": "具备古代大家闺秀应有的女红、诗词等才艺。",
      "坚韧隐忍": "拥有强大的内心承受能力，能在极端屈辱的环境下长期隐忍。"
    }
  }
}

