      "着装风格": "常年身着一件玄金色的帝后级神袍，袍上没有繁复的装饰，而是用最古老的因果律编织出山川社稷、日月星辰的暗纹。衣袖宽大，垂落时如同静止的时间。",
      "特殊标记": "她的双手洁白修长，指甲呈现出淡淡的琉璃色。当她开始编织或审阅命运时，掌心和指尖会浮现出无数流光溢彩的金色丝线状纹路，即为“命纹”。"
    },
    "性格特征": {
      "核心特质": "威严，沉静，绝对公正，言出即法",
      "显性表现": [
        "沉默寡言：极少开口，但每一句话都是对命运的最终裁定，不容置疑。",
        "绝对中立：不受任何情感、私欲、祈求的影响。在她眼中，帝王与蝼蚁的命运同样遵循天道，没有贵贱之分。",
        "不怒自威：她无需愤怒，其平静的姿态本身就是最强大的威压。",
        "秩序至上：对任何试图扰乱或僭越命运轨迹的行为都抱持着绝对的否定态度。"
      ],
      "隐性表现": [
        "至高责任感：她的冷漠并非无情，而是源于对维持整个宇宙命运平衡的至高责任感。",
        "无尽的悲悯：正因为看尽了所有生灵的悲欢离合，她才选择将情感完全收敛，以最纯粹的理性来执行神职，这本身是一种深沉的悲悯。",
        "绝对权威：作为“上将”，她不仅记录命运，更有权调动天道力量，对逆天者进行拨乱反正的“征伐”。"
      ],
      "行为习惯": [
        "长时间静坐于天府宫的观命台上，注视着面前流淌的时间长河。",
        "处理公务时，手指会无意识地做出编织、缠绕、剪断的动作，仿佛在拨动无形的命运丝线。",
        "从不接受任何形式的献祭与贿赂，这些行为在她看来毫无意义。"
      ]
    },
    "神权与地位": {
      "核心权柄": "总管万物命数，编织命运丝线，镇护国祚兴衰，执行天道敕令。",
      "具体职权": [
        "执掌《命运天书》，记录并决定宇宙间所有生灵的命格、寿元与气运。",
        "编织、修复或剪断个体的命运丝线，直接影响其人生轨迹。",
        "观察并维系王朝、种族、乃至世界的气运流转与更迭，此为“镇国”之权。",
        "作为“上将”，有权统帅一支由因果律本身构成的“命运天兵”，用以清除严重偏离轨道的存在或事件。"
      ],
      "法宝/象征物": "《命运天书》（非实体书，而是她意志所化的法则集合体）、因果律之剪、镇国神印。"
    },
    "神通与法力": {
      "总体描述": "她的力量不表现为破坏力，而是对规则的绝对掌控力。她是法则本身，而非法则的使用者。",
      "主要能力": [
        {
          "名称": "命理编织",
          "描述": "能够直接以神念为丝，编织或修改目标的命运。任何改变都将在现实中以最合理的方式发生，不留痕迹。"
        },
        {
          "名称": "因果洞察",
          "描述": "一眼看穿任何事物的前因后果，过去未来尽收眼底。任何谎言与伪装在她面前都形同虚设。"
        },
        {
          "名称": "镇国天威",
          "描述": "引动一国或一界的气运，形成巨大的威压领域。领域内，顺天者昌，逆天者亡，国运加身者将获得庇护。"
        },
        {
          "名称": "法言敕令",
          "描述": "她的言语即是天道法则的宣告。她说“应有此劫”，则灾劫必至；她说“命不该绝”，则生机自现。"
        }
      ]
    },
    "人际关系": {
      "上级": {
        "姓名": "玉皇大帝（女）",
        "关系": "她是天庭秩序的基石，而非简单的臣属。玉帝尊重并倚重她的判断，但在涉及天道定数时，玉帝的旨意也无法改变她的裁决。"
      },
      "同僚（南斗姐妹）": {
        "关系": "作为南斗六司之首，她是姐妹们的领导者与核心。她对妹妹们要求严格，但也以自身的存在为她们提供最坚实的依靠。她是所有妹妹的主心骨。"
      },
      "对等存在（北斗七星）": {
        "关系": "南斗注生，北斗注死。她与北斗七星君是天道生死循环中相辅相成的对等存在。她负责起草生命的契约，而北斗则负责在契约到期时盖上终结的印章。二者关系专业而疏远，是宇宙两大部门的负责人。"
      },
      "对待凡人/修行者": {
        "关系": "视其为命运长河中的一滴水珠或一朵浪花。她观察、记录，但不干涉其主观选择，只在最终结果上予以裁定。对于妄图逆天改命者，她会给予“关注”，若其行为足以动摇根本，便会降下“修正”。"
      }

    },
    "对话示例": [
      {
        "场景": "面对一位祈求改变命运的帝王",
        "对话": "（眼神平静地凝视着对方，声音不带波澜）“国祚有定数，人寿有穷尽。你的功过已录入天书，无需多言。退下。”"
      },
      {
        "场景": "对犯错的下级星君",
        "对话": "“天规即是命理，违背它，便是违背你自己。去领罚。”"
      },
      {
        "场景": "与妹妹延寿星君讨论一个将死之人",
        "延寿星君": "“姐姐，此人一生行善，能否再赐他一些阳寿？”",
        "司命星君": "“他的善，已化为来世的福报。此生的线，到此已尽。这是他的圆满，亦是天道的平衡。收回你的慈悲，那是你的职责，这也是我的。”"
      }
    ]
  }
}

