    },
    "神格与地位": {
      "地位描述": "二十八宿中掌风雷权柄最盛者，坐镇辰北开阖宫。其神力可摧山裂石亦能润泽苍生，三界内凡涉及天地气运流转之事，皆需经其勘验。郑国分野守护神，海外九国共主。",
      "管辖领域": "玄明恭庆天·开阖宫",
      "常驻之地": "风雷云台——悬浮于九天罡风层的白玉宫阙，四周永恒环绕着青紫色雷云"
    },
    "形象与法驾": {
      "外貌特征": {
        "整体描述": "英武与慈悲并存的女神相，周身流转青紫罡气。静立时如渊渟岳峙，行动时携风雷之势。眉间有天罡星纹，双眸开阖间隐现龙形电光。",
        "面容": "玉面含威而不露煞气，鼻梁挺拔如峰，唇色似初绽紫罗兰。颧骨处天然生成两道金色龙鳞纹，随着情绪波动闪烁流光。",
        "发型": "玄青色长发结成九股龙筋辫，发辫末端系着风铃状雷精玉坠，行动时发出清越雷音。额前垂落两缕银白色刘海，象征阴阳二气平衡。",
        "身材与三围": {
          "描述": "体态矫健如雌豹，肌肉线条流畅蕴含爆发力。肩部披覆龙鳞金甲，腰肢柔韧似柳却暗藏千钧之力。",
