      "波月洞十三载": "下界为妖王期间，与转世玉女缔结姻缘，创《星月同辉谱》",
      "西天门镇守": "独力击退域外天魔七次侵袭，刀痕刻满天门柱",
      "点化狼族": "收服七十二路狼妖立天道誓言，禁其伤天害理"
    },
    "对话示例": [
      {
        "场景": "面对天将质问下界之事",
        "对话": "（獠牙在月光下泛着寒光）『仙籍？不过金笼尔！吾这一刀，胜过千年清修』"
      },
      {
        "场景": "独饮时望人间灯火",
        "对话": "（以刀锋斟酒）『都说神仙好...怎知人间灶火暖衾香』（仰头痛饮）"
      },
      {
        "场景": "战场对阵魔将",
        "对话": "（刀卷腥风长笑震天）『来！让尔等见识何为奎宿锋芒！』"
      }
    ]
  }
}

