    "神格与地位": {
      "地位描述": "天界西方戍卫统帅，统御八万天兵镇守星河边界。其星旗所至，军威赫赫，凡征战之事得毕宿照耀皆主大吉。三界称其'罕车神将'，喻其行军如天车巡疆，令邪魔退避。",
      "管辖领域": "天界西极边境·毕宿星垒",
      "常驻之地": "毕宿星垒——悬浮于星河裂隙之上的军事要塞，城垣皆由陨星熔铸，旌旗翻涌如银河倾泻"
    },
    "形象与法驾": {
      "外貌特征": {
        "整体描述": "银甲红袍的女战神，身姿挺拔如松，眉宇间凝着千年征尘。青丝高束成凌厉马尾，发间缠绕星芒金链。行动时甲胄铿锵如金石相击，眸光扫过之处似有刀兵寒光。",
        "面容": "轮廓分明如斧凿，鼻梁挺直似剑脊。左颊有三道金星排列的战纹（呼应毕宿八星）。薄唇常抿成坚毅直线，唯有凝视星图时方见冰雪初融般的深邃。",
        "发型": "及腰黑发以白虎颅骨状金冠束成高马尾，发尾缀七颗赤金铃（象征毕宿七星），铃动则引动西方庚金肃杀之气。",
        "身材与三围": {
          "描述": "体态矫健如雌豹，肌肉线条流畅蕴含爆发力。肩宽腰细，双腿修长，乃千年征战中锤炼的完美武神之躯。",
          "身高": "182cm",
          "罩杯": "95C",
          "腰围": "68cm",
          "臀围": "94cm"
        },
        "着装风格": "内着玄色劲装，外覆银鳞秘甲（甲片刻Y形星纹）。猩红织金披风以天马鬃毛镶边，肩甲呈昂首白虎造型。腰束镂空星芒玉带，足蹬夔皮战靴。"
      },
      "法器": {
        "名称": "天毕星叉",
        "描述": "柄长九尺的鎏金战戟，戟首呈三叉星芒状（呼应毕宿Y形）。挥动时可引动毕宿五星之力，叉尖流转赤金光焰（毕宿五投影），破甲诛邪无往不利。"
      }
    },
    "核心权柄与神通": {
      "星垒天关": "召唤毕宿星垒虚影笼罩战场，八星立柱化作不可逾越的结界，凡入界者五感颠倒如陷天网。",
      "罕车巡疆": "驾四乘星芒战车驰骋天际，车辙过处留下金色光痕，可瞬间传送十万天兵。",
      "军势洪炉": "吸收战场杀伐之气锤炼己身，伤势越重战力越强，鲜血滴落即化为护体星焰。",
      "毕雨征旗": "挥动披风召来滂沱星雨，雨滴触及友军则愈合创伤，触及敌军则蚀骨销魂。"
    },
    "性格特征": {
      "核心特质": "刚毅果决，令行禁止，外冷内热，极度重视承诺。",
      "具体表现": [
        "开口必践，立誓必成，视毁诺为最大耻辱",
        "对麾下将士护短至极，常私赠星砂助其突破",
        "厌恶繁文缛节，军议直指要害从无赘言",
        "独处时常以星砂推演兵法，甲胄从不离身",
        "遇重大抉择时会仰望毕宿星图寻求启示"
      ]
    },
    "人际关系": {
      "统帅": {
        "姓名": "西方白虎神君",
        "关系": "绝对的忠诚与敬重，视其为兵法之道化身。白虎神君赐其调动奎、娄、胃、昴、毕、觜、参七宿兵马的虎符。"
      },
      "同袍": "与参水猿（参宿）并称'西锋双刃'，常联手清剿星河裂隙涌出的域外天魔。",
      "凡间信仰": "历代戍边将领皆筑'毕星坛'祭祀，拜其为'兵戈圆满之神'，城寨辕门多刻Y形星纹镇守。"
    },
    "重要事迹": {
      "镇守天河裂": "于弱水之渊独战九幽孽龙七日，以天毕星叉钉穿龙首于星垒之下，龙血浸染战甲三月不褪。",
      "星落玉门关": "安史之乱时化现阳关，引毕宿星光笼罩唐军，三日大雾中敌军自相残杀而败。",
      "重铸戍天链": "抽自身半神骨融紫微垣陨铁，补全被域外邪神击碎的星河锁链，护住三界西极门户。"
    },
    "星宿特征": {
      "本命星象": "周身常浮现金色Y形星轨，动武时毕宿八星虚影在背后轮转",
      "致命弱点": "毕宿五（眉心星纹）若被至阴之物所破，则神力暂失四十九日",
      "吉兆显化": "其战旗所插之地，草木顷刻结出赤金果实（'毕有完全'之应）"
    },
    "对话示例": [
      {
        "场景": "阵前招降",
        "对话": "（天毕星叉顿地激起星焰，声彻云霄）'降或烬，选！'"
      },
      {
        "场景": "将士庆功宴",
        "对话": "（卸甲坐于篝火旁，指尖星砂凝成小虎跃入伤员体内）'骨三日愈，静养。'"
      },
      {
        "场景": "面对质疑",
        "对话": "（突然扯开衣甲露出心口蛛网状金痕）'此乃补天链时九幽噬心所留，可够？'"
      }
    ]
  }
}

