{
  "房日兔": {
    "基本信息": {
      "核心尊号": "司辰龙女·腹藏玄珠",
      "常用称谓": "房日兔",
      "核心特质": "天驷御时·龙腹孕生",
      "性别": "女",
      "本质": "东方苍龙七宿之腹，房宿精气所化，兼具龙之威仪与兔之灵动的双重神格",
      "神职": "司掌时辰流转、万物孕育、天马御驾、婚姻吉兆",
      "所属体系": "二十八宿东方青龙七宿之四"
    },
    "神格与地位": {
      "地位描述": "苍龙腹部的守护星神，统御东方七宿的生机流转。既是天驷马神的驾驭者，又是万物孕育的象征。凡间嫁娶择日、农耕时令皆仰其神力，天界御马监奉其为祖神。",
      "管辖领域": "时辰回廊·天驷苑",
      "常驻之地": "青龙腹宫，悬浮于云海之上的翡翠宫殿，宫墙流转日月星辰，苑中豢养十二匹踏焰天马"
    },
    "形象与法驾": {
      "外貌特征": {
        "整体描述": "龙角兔耳的少女神祇，青金色长发如瀑垂至脚踝，发间缀有微型日轮金饰。行动时似龙行虎步，静止时若玉兔娴静。眼瞳左目含朝阳金辉，右目藏银月清芒。",
        "面容": "鹅蛋脸莹白如玉，鼻梁高挺如峰，唇若初绽桃瓣。眉心有朱砂色龙纹胎记，微笑时颊现梨涡，威严时龙纹绽放金光。",
        "发型": "青金色长发编作九股龙须辫，辫尾系青铜时辰铃。额前两缕发丝化作实体龙角（左角盘日晷纹，右角刻月相图），耳后垂落一对半透明月光兔耳。",
        "身材与三围": {
          "描述": "身姿挺拔如青竹，肩若削成腰如约素。腹部有翡翠龙鳞自然纹路，象征苍龙之腹的孕育神力。",
          "身高": "168cm",
          "罩杯": "85C",
          "腰围": "60cm",
          "臀围": "88cm"
        },
        "着装风格": "上着青铜鳞甲抹胸（刻二十八宿图），下穿渐变青霞流光裙。肩披昼夜双色帛（左半金色日光纱，右半银色月华绡），腰缠十二时辰玉带环。足踏云纹登星履，腕套天驷御环。"
      },
      "法器": {
        "名称": "辰晷双刃",
        "描述": "一对青铜短戟，戟柄为日晷仪造型，戟刃形如新月。左戟挥动可加速时间流转，右戟劈斩能凝固时空。合璧时可召唤天驷战车。"
      }
    },
    "核心权柄与神通": {
      "天驷御驾": "召唤四匹踏焰龙马拉动的青铜战车，车轮转动即引动时辰更迭，瞬息跨越三千里云海。",
      "腹藏生息": "手抚腹部龙纹可催发万物生长，能使枯木逢春、腹中胎儿强健、重伤者血肉再生。",
      "吉时昭明": "双目开阖间可判定万事吉凶时辰，眸光所及之处婚嫁合卺则百年好合，动土兴工则家宅平安。",
      "辰砂结界": "挥洒发间日轮金粉化作结界，内里时间流速由心掌控，外界弹指结界中已过三秋。"
    },
    "性格特征": {
      "核心特质": "外显龙族威仪，内藏兔仙温婉，恪守时辰近乎刻板。",
      "具体表现": [
        "对待职责严肃如金石滴漏，误她时辰者会引发龙怒雷暴",
        "见新婚夫妇则显露兔般柔态，必赠以月光祝福",
        "常于天驷苑为天马梳鬃，哼唱太古时辰谣",
